 document.body.append(el);const modal=new tabler.Modal(el);el.addEventListener('hidden.bs.modal',()=>{modal.dispose();el.remove()},{once:true});
 $('#blood-type-form',el).onsubmit=event=>{event.preventDefault();try{D.recordBloodType(donorId,{bloodType:$('#exam-blood-type',el).value,reference:$('#exam-reference',el).value,reason:$('#exam-reason',el).value,examConfirmed:$('#exam-confirmed',el).checked?'on':'',voluntaryId:request?.id,expectedVersion:request?.version});modal.hide();render();if(values){const form=$('#donation-form');for(const input of form?.elements||[]){if(input.type==='checkbox')input.checked=values[input.name]==='on';else if(input.name&&Object.hasOwn(values,input.name))input.value=values[input.name]}}H.toast(request?.kind==='blood_type_check'?'تم الفحص وتسجيل الفصيلة دون احتساب تبرع.':'تم تسجيل نتيجة فصيلة الدم.')}catch(error){$('#blood-type-error',el).textContent=error.message}};modal.show();
