 if(!requests.length){H.toast('لا توجد حملة مناسبة نشطة لهذا المتبرع.','info');return}
 const el=document.createElement('div');el.className='modal modal-blur fade';el.tabIndex=-1;el.setAttribute('aria-labelledby','invitation-title');
 el.innerHTML=`<div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="invitation-form"><div class="modal-header"><h2 class="modal-title" id="invitation-title">دعوة ${e(donor.name)} للتبرع</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="إغلاق"></button></div><div class="modal-body">${select('invitation-request','الحملة',requests.map(r=>[r.id,`${r.bloodType} · ${r.units} وحدات · ${r.id}`]),requests[0].id,'required')}<p class="text-secondary small">تصل الدعوة داخل التطبيق، ويستطيع المتبرع قبولها أو الاعتذار عنها. لا تُضاف نقاط قبل التبرع الفعلي.</p><div id="invitation-error" class="text-danger small" role="alert"></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">تراجع</button><button type="submit" class="btn btn-primary">إرسال الدعوة</button></div></form></div></div>`;
 document.body.append(el);const modal=new tabler.Modal(el);
 el.addEventListener('hidden.bs.modal',()=>{modal.dispose();el.remove()},{once:true});
 $('#invitation-form',el).onsubmit=event=>{event.preventDefault();try{D.inviteDonor($('#invitation-request',el).value,donorId);modal.hide();render();H.toast('تم إرسال دعوة التبرع بنجاح.')}catch(error){$('#invitation-error',el).textContent=error.message}};
