function appointmentEditor(responseId,change=false){
 const response=state.donor_responses.find(r=>r.id===responseId);if(!response)return;
 const a=response.appointment,version=a?.version||response.appointmentRevision||0,initial=change?'':a?.requestedAt||a?.scheduledAt||'';
 const localInput=value=>{const d=new Date(value);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`};
 const el=document.createElement('div');el.className='modal modal-blur fade';el.tabIndex=-1;el.setAttribute('aria-labelledby','appointment-title');
 el.innerHTML=`<div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="appointment-form"><div class="modal-header"><h2 class="modal-title" id="appointment-title">${change?'طلب وقت آخر':'تحديد موعد حضور المتبرع'}</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="إغلاق"></button></div><div class="modal-body"><p><strong>${e(person(response.donorId)?.name)}</strong></p>${a?`<div class="mb-3">${appointmentSummary(response)}</div>`:''}${field('appointment-time',change?'الوقت الذي يناسبك':'تاريخ ووقت الحضور','datetime-local',initial?localInput(initial):'',`required min="${localInput(new Date(Date.now()+60000))}"`)}<p class="text-secondary small">${change?'يُرسل الوقت للمؤسسة لتراجعه وترسل موعدًا للموافقة عليه.':'سيصل الموعد للمتبرع في إشعاراته ليقبله أو يطلب وقتًا آخر.'} الأوقات حسب توقيت هذا الجهاز.</p><div id="appointment-error" class="text-danger small" role="alert"></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">تراجع</button><button type="submit" class="btn btn-primary">${change?'إرسال الوقت للمؤسسة':'إرسال الموعد للمتبرع'}</button></div></form></div></div>`;
 const previous=document.activeElement;document.body.append(el);const modal=new tabler.Modal(el);
 el.addEventListener('hidden.bs.modal',()=>{modal.dispose();el.remove();(previous?.isConnected?previous:$('#page-title'))?.focus()},{once:true});
 $('#appointment-form',el).onsubmit=event=>{event.preventDefault();try{
  const input=$('#appointment-time',el).value,scheduledAt=new Date(input).toISOString();
  if(change)D.replyAppointment(responseId,{status:'change_requested',requestedAt:scheduledAt,expectedVersion:version});
  else D.scheduleAppointment(responseId,{scheduledAt,expectedVersion:version});
  modal.hide();render();H.toast(change?'تم إرسال طلب تغيير الموعد للمؤسسة.':'تم إرسال الموعد للمتبرع للموافقة عليه.');
 }catch(error){$('#appointment-error',el).textContent=error.message}};
 modal.show();
}
function reasonModal(title,action,success='تم حفظ التغيير بنجاح.'){const el=document.createElement('div');el.className='modal modal-blur fade';el.tabIndex=-1;el.setAttribute('aria-labelledby','reason-heading');el.innerHTML=`<div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="reason-form"><div class="modal-header"><h2 class="modal-title" id="reason-heading">${e(title)}</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="إغلاق"></button></div><div class="modal-body"><label class="form-label" for="reason">السبب (يُحفظ في سجل التدقيق)</label><textarea class="form-control" id="reason" name="reason" required minlength="5" maxlength="400" rows="3"></textarea><div class="text-danger small mt-2" id="reason-error" role="alert"></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">تراجع</button><button class="btn btn-danger" type="submit">تأكيد وتسجيل السبب</button></div></form></div></div>`;document.body.append(el);const modal=new tabler.Modal(el);el.addEventListener('hidden.bs.modal',()=>{modal.dispose();el.remove()},{once:true});$('#reason-form',el).onsubmit=event=>{event.preventDefault();try{action($('#reason',el).value);modal.hide();render();H.toast(success)}catch(err){$('#reason-error',el).textContent=err.message}};modal.show()}
function submitForm(id,action){const form=$('#'+id);if(!form)return;form.onsubmit=async ev=>{ev.preventDefault();H.clearFormErrors(form);const btn=$('[type="submit"]',form),text=btn.innerHTML;btn.disabled=true;btn.innerHTML='<span class="spinner-border spinner-border-sm"></span> جارٍ الحفظ…';try{await action(Object.fromEntries(new FormData(form)));}catch(err){H.alertForm(err.message);btn.disabled=false;btn.innerHTML=text}}}
